{"success": true, "name": "visualization/hermes-dashboard", "file": "scripts/hermes_dashboard_api.py", "content": "#!/usr/bin/env python3
"""
Hermes Dashboard API — serves Hermes data as JSON endpoints for the frontend.
Connects to state.db (sessions, messages, delegations) and kanban.db (tasks).
Copy-ready from the hermes-dashboard skill. Run:
  DASHBOARD_PORT=8502 /Users/neosteinhoff/.hermes/hermes-agent/venv/bin/python scripts/hermes_dashboard_api.py
"""
import json
import os
import sqlite3
import time
from datetime import datetime, timedelta
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

HERMES_HOME = os.environ.get("HERMES_HOME", "/Users/neosteinhoff/.hermes")
STATE_DB = os.path.join(HERMES_HOME, "state.db")
KANBAN_DB = os.path.join(HERMES_HOME, "kanban.db")
CRONS_JSON = os.path.join(HERMES_HOME, "crons.json")


def get_state_conn():
    conn = sqlite3.connect(STATE_DB)
    conn.row_factory = sqlite3.Row
    return conn


def get_kanban_conn():
    conn = sqlite3.connect(KANBAN_DB)
    conn.row_factory = sqlite3.Row
    return conn


def row_to_dict(row):
    if row is None:
        return None
    return {k: row[k] for k in row.keys()}


def ts_to_iso(ts):
    """Convert unix timestamp float/int to ISO string for frontend display."""
    if ts is None:
        return None
    try:
        return datetime.fromtimestamp(float(ts)).isoformat()
    except (ValueError, TypeError, OverflowError):
        return str(ts)


def convert_session_timestamps(d):
    for field in ("started_at", "ended_at", "last_activity_at"):
        if field in d and d[field] is not None:
            d[field] = ts_to_iso(d[field])
    return d


class HermesDashboardAPI(BaseHTTPRequestHandler):
    def do_GET(self):
        parsed = urlparse(self.path)
        path = (parsed.path.rstrip("/") or "/")
        params = parse_qs(parsed.query)

        routes = {
            "/api/overview": self._overview,
            "/api/sessions": self._sessions,
            "/api/session": self._session_detail,
            "/api/tasks": self._kanban_tasks,
            "/api/task": self._kanban_task_detail,
            "/api/delegations": self._delegations,
            "/api/crons": self._crons,
            "/api/costs": self._costs,
            "/api/models": self._models,
        }
        handler = routes.get(path)
        if handler:
            self._send_json(handler(params))
        else:
            self._send_json({"error": "Not found"}, 404)

    def do_POST(self):
        parsed = urlparse(self.path)
        path = (parsed.path.rstrip("/") or "/")
        routes = {"/api/tasks/create": self._create_task}
        handler = routes.get(path)
        if handler:
            length = int(self.headers.get("Content-Length", 0))
            body = json.loads(self.rfile.read(length)) if length else {}
            self._send_json(handler(body))
        else:
            self._send_json({"error": "Not found"}, 404)

    def do_OPTIONS(self):
        self._send_json({"ok": True})

    def _send_json(self, data, status=200):
        body = json.dumps(data, indent=2, default=str)
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.end_headers()
        self.wfile.write(body.encode())

    def _overview(self, params):
        conn = get_state_conn()
        kconn = get_kanban_conn()
        now = datetime.now()
        since = (now - timedelta(days=7)).isoformat()

        sessions = conn.execute("SELECT COUNT(*) c FROM sessions WHERE started_at > ?", (since,)).fetchone()
        active_sessions = conn.execute("SELECT COUNT(*) c FROM sessions WHERE ended_at IS NULL").fetchone()
        total_tokens = conn.execute("SELECT COALESCE(SUM(input_tokens + output_tokens),0) t FROM sessions WHERE started_at > ?", (since,)).fetchone()
        total_cost = conn.execute("SELECT COALESCE(SUM(actual_cost_usd),0) c FROM sessions WHERE started_at > ?", (since,)).fetchone()
        pending_tasks = kconn.execute("SELECT COUNT(*) c FROM tasks WHERE status IN ('pending','in_progress')").fetchone()
        total_tasks = kconn.execute("SELECT COUNT(*) c FROM tasks").fetchone()
        delegations = conn.execute("SELECT COUNT(*) c FROM async_delegations WHERE state='running'").fetchone()
        return {
            "sessions_7d": sessions["c"], "active_sessions": active_sessions["c"],
            "tokens_7d": total_tokens["t"], "cost_7d_usd": round(total_cost["c"], 4),
            "pending_tasks": pending_tasks["c"], "total_tasks": total_tasks["c"],
            "active_delegations": delegations["c"], "timestamp": now.isoformat(),
        }

    def _sessions(self, params):
        limit = int(params.get("limit", [50])[0])
        conn = get_state_conn()
        rows = conn.execute("""
            SELECT id, title, started_at, ended_at, end_reason, model,
                   input_tokens, output_tokens, actual_cost_usd, message_count,
                   session_key, display_name
            FROM sessions ORDER BY started_at DESC LIMIT ?""", (limit,)).fetchall()
        out = []
        for r in rows:
            d = row_to_dict(r)
            convert_session_timestamps(d)
            out.append(d)
        return out

    def _session_detail(self, params):
        sid = params.get("id", [None])[0]
        if not sid:
            return {"error": "missing ?id="}
        conn = get_state_conn()
        sess = conn.execute("SELECT * FROM sessions WHERE id=? OR session_key=?", (sid, sid)).fetchone()
        if not sess:
            return {"error": "session not found"}
        msgs = conn.execute("""SELECT id, role, content, tool_name, timestamp, finish_reason
            FROM messages WHERE session_id=? ORDER BY timestamp""", (sess["id"],)).fetchall()
        return {"session": row_to_dict(sess),
                "messages": [row_to_dict(r) for r in msgs[:200]]}

    def _kanban_tasks(self, params):
        status = params.get("status", [None])[0]
        conn = get_kanban_conn()
        if status:
            rows = conn.execute("SELECT * FROM tasks WHERE status=? ORDER BY created_at DESC", (status,)).fetchall()
        else:
            rows = conn.execute("SELECT * FROM tasks ORDER BY created_at DESC").fetchall()
        return [row_to_dict(r) for r in rows]

    def _kanban_task_detail(self, params):
        tid = params.get("id", [None])[0]
        if not tid:
            return {"error": "missing ?id="}
        conn = get_kanban_conn()
        task = conn.execute("SELECT * FROM tasks WHERE id=?", (tid,)).fetchone()
        if not task:
            return {"error": "task not found"}
        comments = conn.execute("SELECT * FROM task_comments WHERE task_id=? ORDER BY created_at", (tid,)).fetchall()
        events = conn.execute("SELECT * FROM task_events WHERE task_id=? ORDER BY created_at", (tid,)).fetchall()
        return {"task": row_to_dict(task),
                "comments": [row_to_dict(c) for c in comments],
                "events": [row_to_dict(e) for e in events]}

    def _delegations(self, params):
        conn = get_state_conn()
        rows = conn.execute("""SELECT delegation_id, origin_session, state, dispatched_at,
            completed_at, task_json, delivery_state FROM async_delegations ORDER BY dispatched_at DESC""").fetchall()
        return [row_to_dict(r) for r in rows]

    def _crons(self, params):
        if not os.path.exists(CRONS_JSON):
            return []
        with open(CRONS_JSON) as f:
            return json.load(f)

    def _costs(self, params):
        conn = get_state_conn()
        rows = conn.execute("""
            SELECT model, billing_provider, SUM(input_tokens) input_tok,
                   SUM(output_tokens) output_tok, SUM(cache_read_tokens) cache_tok,
                   SUM(estimated_cost_usd) est_cost, SUM(actual_cost_usd) act_cost, COUNT(*) sess_count
            FROM sessions GROUP BY model, billing_provider ORDER BY est_cost DESC""").fetchall()
        return [row_to_dict(r) for r in rows]

    def _models(self, params):
        conn = get_state_conn()
        rows = conn.execute("""
            SELECT model, SUM(input_tokens) total_in, SUM(output_tokens) total_out,
                   SUM(actual_cost_usd) total_cost, COUNT(*) sess_count
            FROM sessions GROUP BY model ORDER BY total_cost DESC""").fetchall()
        return [row_to_dict(r) for r in rows]

    def _create_task(self, body):
        conn = get_kanban_conn()
        now = datetime.now().isoformat()
        cur = conn.execute("""INSERT INTO tasks (title, body, status, priority, created_by, created_at)
            VALUES (?, ?, 'pending', ?, ?, ?)""", (
            body.get("title", "Untitled"), body.get("body", ""),
            body.get("priority", 3), body.get("created_by", "dashboard"), now))
        conn.commit()
        return {"id": cur.lastrowid, "status": "created"}


if __name__ == "__main__":
    port = int(os.environ.get("DASHBOARD_PORT", 8502))
    server = HTTPServer(("0.0.0.0", port), HermesDashboardAPI)
    print(f"[Hermes Dashboard API] serving on http://localhost:{port}")
    server.serve_forever()
