<title>Hermes Command Center</title>
<style>
  :root {
    --bg:#1e1e2d; --panel:#27293d; --panel2:#2f3148; --accent:#00d4ff;
    --green:#00d97e; --orange:#ff9f43; --red:#f5365c; --purple:#b388ff;
    --text:#e0e0f0; --dim:#8a8aa0; --border:#3a3c55;
  }
  *{margin:0;padding:0;box-sizing:border-box;}
  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:var(--bg);color:var(--text);}
  .topbar{background:var(--panel);padding:12px 24px;border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;}
  .topbar h1{font-size:18px;color:var(--accent);}
  .topbar .status{font-size:13px;color:var(--dim);}
  .layout{display:flex;}
  .sidebar{width:220px;background:var(--panel);min-height:100vh;border-right:1px solid var(--border);padding:16px 0;}
  .sidebar a{display:block;padding:12px 24px;color:var(--dim);text-decoration:none;font-size:14px;transition:all .2s;}
  .sidebar a:hover,.sidebar a.active{background:var(--panel2);color:var(--accent);border-left:3px solid var(--accent);}
  .main{flex:1;padding:24px;}
  .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-bottom:24px;}
  .card{background:var(--panel);border-radius:12px;padding:20px;border:1px solid var(--border);}
  .card .label{font-size:13px;color:var(--dim);margin-bottom:8px;}
  .card .value{font-size:28px;font-weight:700;color:var(--accent);}
  .card.green .value{color:var(--green);}
  .card.orange .value{color:var(--orange);}
  .card.purple .value{color:var(--purple);}
  .panel{background:var(--panel);border-radius:12px;padding:20px;border:1px solid var(--border);margin-bottom:24px;}
  .panel h2{font-size:16px;margin-bottom:16px;color:var(--text);}
  table{width:100%;border-collapse:collapse;font-size:13px;}
  th{text-align:left;padding:10px 12px;color:var(--accent);border-bottom:2px solid var(--border);font-weight:600;}
  td{padding:10px 12px;border-bottom:1px solid var(--border);}
  .badge{padding:2px 10px;border-radius:10px;font-size:11px;font-weight:600;}
  .badge-todo{background:rgba(0,212,255,.15);color:var(--accent);}
  .badge-done{background:rgba(0,217,126,.15);color:var(--green);}
  .badge-ready{background:rgba(179,136,255,.15);color:var(--purple);}
  .badge-blocked{background:rgba(245,54,92,.15);color:var(--red);}
  .badge-other{background:rgba(138,138,160,.15);color:var(--dim);}
  .refresh{background:var(--accent);color:#000;border:none;padding:8px 16px;border-radius:8px;cursor:pointer;font-weight:600;}
  .nav-section{font-size:11px;text-transform:uppercase;color:var(--dim);padding:12px 24px 4px;letter-spacing:1px;}
</style>
