<body>
<div class="topbar">
  <h1>⚡ Hermes Command Center</h1>
  <div class="status"><span id="last-update">Loading...</span>
    <button class="refresh" onclick="loadAll()">↻ Refresh</button></div>
</div>
<div class="layout">
  <div class="sidebar">
    <div class="nav-section">DASHBOARD</div>
    <a href="#" class="active" onclick="showView('overview')">Overview</a>
    <a href="#" onclick="showView('tasks')">Kanban Tasks</a>
    <a href="#" onclick="showView('sessions')">Sessions</a>
    <a href="#" onclick="showView('delegations')">Delegations</a>
    <a href="#" onclick="showView('costs')">Cost & Models</a>
    <div class="nav-section">SYSTEMS</div>
    <a href="#" onclick="showView('crons')">Cron Jobs</a>
  </div>
  <div class="main">
    <div id="view-overview">
      <div class="cards">
        <div class="card"><div class="label">Active Sessions</div><div class="value" id="stat-active-sessions">-</div></div>
        <div class="card green"><div class="label">Sessions (7d)</div><div class="value" id="stat-sessions-7d">-</div></div>
        <div class="card orange"><div class="label">Tokens (7d)</div><div class="value" id="stat-tokens-7d">-</div></div>
        <div class="card purple"><div class="label">Cost (7d USD)</div><div class="value" id="stat-cost-7d">-</div></div>
        <div class="card"><div class="label">Pending Tasks</div><div class="value" id="stat-pending-tasks">-</div></div>
        <div class="card green"><div class="label">Total Tasks</div><div class="value" id="stat-total-tasks">-</div></div>
      </div>
      <div class="panel"><h2>📊 Quick Stats</h2>
        <div class="cards"><div class="card purple"><div class="label">Active Delegations</div><div class="value" id="stat-active-delegations">-</div></div></div>
      </div>
    </div>
    <div id="view-tasks" style="display:none"><div class="panel"><h2>📋 Kanban Tasks (<span id="task-count">0</span>)</h2>
      <table><thead><tr><th>ID</th><th>Title</th><th>Status</th><th>Priority</th><th>Created</th></tr></thead><tbody id="tasks-body"></tbody></table></div></div>
    <div id="view-sessions" style="display:none"><div class="panel"><h2>💬 Recent Sessions</h2>
      <table><thead><tr><th>Title</th><th>Model</th><th>Msgs</th><th>Started</th><th>Cost</th></tr></thead><tbody id="sessions-body"></tbody></table></div></div>
    <div id="view-delegations" style="display:none"><div class="panel"><h2>🤖 Async Delegations</h2>
      <table><thead><tr><th>ID</th><th>State</th><th>Dispatched</th><th>Completed</th><th>Delivery</th></tr></thead><tbody id="delegations-body"></tbody></table></div></div>
    <div id="view-costs" style="display:none">
      <div class="panel"><h2>💰 Cost by Model (7d)</h2>
        <table><thead><tr><th>Model</th><th>Provider</th><th>Input Tok</th><th>Output Tok</th><th>Est Cost</th><th>Act Cost</th><th>Sessions</th></tr></thead><tbody id="costs-body"></tbody></table></div>
      <div class="panel"><h2>🧠 Model Usage</h2>
        <table><thead><tr><th>Model</th><th>Total In</th><th>Total Out</th><th>Total Cost</th><th>Sessions</th></tr></thead><tbody id="models-body"></tbody></table></div></div>
    <div id="view-crons" style="display:none"><div class="panel"><h2>⏰ Cron Jobs</h2><div id="crons-body"></div></div></div>
  </div>
</div>
<script>
const API='http://localhost:8502/api';
async function apiGet(p){const r=await fetch(API+p);if(!r.ok)throw new Error('HTTP '+r.status);return r.json();}
function fmtNum(n){if(n==null)return'0';if(n>=1e9)return(n/1e9).toFixed(1)+'B';if(n>=1e6)return(n/1e6).toFixed(1)+'M';if(n>=1e3)return(n/1e3).toFixed(1)+'K';return String(n);}
function statusBadge(s){const m={todo:'badge-todo',done:'badge-done',ready:'badge-ready',blocked:'badge-blocked',in_progress:'badge-todo',running:'badge-todo'};return `<span class="badge ${m[s]||'badge-other'}">${s}</span>`;}
function showView(v){document.querySelectorAll('.sidebar a').forEach(a=>a.classList.remove('active'));event.target.classList.add('active');['overview','tasks','sessions','delegations','costs','crons'].forEach(x=>{document.getElementById('view-'+x).style.display=(x===v)?'block':'none';});if(v==='tasks')loadTasks();if(v==='sessions')loadSessions();if(v==='delegations')loadDelegations();if(v==='costs')loadCosts();if(v==='crons')loadCrons();}
async function loadAll(){const o=await apiGet('/overview');document.getElementById('stat-active-sessions').textContent=o.active_sessions;document.getElementById('stat-sessions-7d').textContent=o.sessions_7d;document.getElementById('stat-tokens-7d').textContent=fmtNum(o.tokens_7d);document.getElementById('stat-cost-7d').textContent='$'+o.cost_7d_usd.toFixed(2);document.getElementById('stat-pending-tasks').textContent=o.pending_tasks;document.getElementById('stat-total-tasks').textContent=o.total_tasks;document.getElementById('stat-active-delegations').textContent=o.active_delegations;document.getElementById('last-update').textContent='Updated: '+new Date(o.timestamp).toLocaleTimeString();}
async function loadTasks(){const t=await apiGet('/tasks');document.getElementById('task-count').textContent=t.length;document.getElementById('tasks-body').innerHTML=t.map(x=>`<tr><td>${x.id||'-'}</td><td>${x.title||''}</td><td>${statusBadge(x.status)}</td><td>${x.priority||'-'}</td><td>${x.created_at?new Date(x.created_at).toLocaleDateString():'-'}</td></tr>`).join('');}
async function loadSessions(){const s=await apiGet('/sessions?limit=50');document.getElementById('sessions-body').innerHTML=s.map(x=>`<tr><td>${(x.title||x.display_name||'Untitled').slice(0,50)}</td><td>${x.model||'-'}</td><td>${x.message_count||0}</td><td>${x.started_at?new Date(x.started_at).toLocaleDateString():'-'}</td><td>$${((x.actual_cost_usd||0)).toFixed(2)}</td></tr>`).join('');}
async function loadDelegations(){const d=await apiGet('/delegations');document.getElementById('delegations-body').innerHTML=d.map(x=>`<tr><td>${x.delegation_id||'-'}</td><td>${statusBadge(x.state)}</td><td>${x.dispatched_at?new Date(x.dispatched_at).toLocaleString():'-'}</td><td>${x.completed_at?new Date(x.completed_at).toLocaleString():'-'}</td><td>${x.delivery_state||'-'}</td></tr>`).join('');}
async function loadCosts(){const c=await apiGet('/costs');document.getElementById('costs-body').innerHTML=c.map(x=>`<tr><td>${x.model||'-'}</td><td>${x.billing_provider||'-'}</td><td>${fmtNum(x.input_tok)}</td><td>${fmtNum(x.output_tok)}</td><td>$${((x.est_cost||0)).toFixed(2)}</td><td>$${((x.act_cost||0)).toFixed(2)}</td><td>${x.sess_count||0}</td></tr>`).join('');const m=await apiGet('/models');document.getElementById('models-body').innerHTML=m.map(x=>`<tr><td>${x.model||'-'}</td><td>${fmtNum(x.total_in)}</td><td>${fmtNum(x.total_out)}</td><td>$${((x.total_cost||0)).toFixed(2)}</td><td>${x.sess_count||0}</td></tr>`).join('');}
async function loadCrons(){const c=await apiGet('/crons');document.getElementById('crons-body').innerHTML=c.length?`<table><thead><tr><th>Name</th><th>Schedule</th><th>Enabled</th></tr></thead><tbody>${c.map(x=>`<tr><td>${x.name||x.id||'-'}</td><td>${x.schedule||'-'}</td><td>${x.enabled?'OK':'X'}</td></tr>`).join('')}</tbody></table>`:'<p style="color:var(--dim)">No cron jobs configured.</p>';}
loadAll().catch(e=>console.error(e));
setInterval(()=>loadAll().catch(()=>{}),30000);
</script>
</body>
</html>
