{"content": "1|/* ═══════════════════════════════════════════════════
2|   THE ZEG — Command Center View
3|   ═══════════════════════════════════════════════════ */
4|
5|export function init(container, api) {
6|  render(container, api);
7|}
8|
9|export async function refresh(_api) {
10|  const container = document.querySelector('.main-content');
11|  if (container) render(container, _api || window.ZEG?.api);
12|}
13|
14|function render(container, api) {
15|  container.innerHTML = `
16|    <div id="command-center">
17|      <!-- Traffic Light Status (Neil Patel) -->
18|      <div id="cc-traffic-light" style="margin-bottom: 8px;"></div>
19|      <!-- Quick Actions Bar (Brian Dean) -->
20|      <div class="quick-actions" id="cc-quick-actions"></div>
21|      <div class="stat-grid" id="cc-stats"></div>
22|      <div class="card">
23|        <div class="card-header">Token Breakdown (7d)</div>
24|        <div class="stat-grid" id="cc-tokens"></div>
25|      </div>
26|      <div class="card">
27|        <div class="card-header">Model Costs (7d)</div>
28|        <table id="cc-models-table">
29|          <thead>
30|            <tr><th>Model</th><th>Provider</th><th>Input</th><th>Output</th><th>Cache Read</th><th>Cache Creation</th><th>Reasoning</th><th>Sessions</th><th>Cost (USD)</th></tr>
31|          </thead>
32|          <tbody></tbody>
33|        </table>
34|      </div>
35|      <div class="card">
36|        <div class="card-header">Active Sessions</div>
37|        <table id="cc-sessions-table">
38|          <thead>
39|            <tr><th>ID</th><th>Name</th><th>Model</th><th>Input</th><th>Output</th><th>Cache</th><th>Source</th></tr>
40|          </thead>
41|          <tbody></tbody>
42|        </table>
43|      </div>
44|      <div class="stat-grid">
45|        <div class="stat blue"><div class="num" id="cc-skills">○</div><div class="lbl">Skills Loaded</div></div>
46|        <div class="stat purple"><div class="num" id="cc-profiles">○</div><div class="lbl">Profiles</div></div>
47|        <div class="stat green"><div class="num" id="cc-memory">○</div><div class="lbl">Memory Facts</div></div>
48|        <div class="stat orange"><div class="num" id="cc-gbrain">○</div><div class="lbl">GBrain Notes</div></div>
49|        <div class="stat blue"><div class="num" id="cc-pipelines">○</div><div class="lbl">Pipelines</div></div>
50|      </div>
51|    </div>
52|  `;
53|  loadData(api);
54|}
55|
56|async function loadData(api) {
57|  // api.fetch is safe — data comes from our own API server (not user input)
58|  if (!api) api = window.ZEG?.api;
59|  if (!api) return;
60|  const [data, qa] = await Promise.all([api.fetch('/api/command-center'), api.fetch('/api/quick-actions')]);
61|  if (!data) { showFallback(); return; }
62|
63|  // Quick Actions bar (Brian Dean: clear next actions)
64|  const qab = document.getElementById('cc-quick-actions');
65|  if (qab && qa) qab.innerHTML = qa.actions.map(a => '<div class="quick-action' + (a.priority === 'high' ? ' high' : '') + '" onclick="navigateTo(\'' + a.view + '\')"><span class="qicon">◈</span> ' + a.label + '</div>').join('') || '<div class="quick-action"><span class="qicon">○</span> No urgent actions</div>';
66|
67|  // Traffic light status (Neil Patel style)
68|  const tlEl = document.getElementById('cc-traffic-light');
69|  if (tlEl) {
70|    const activeSessions = data.stats?.active_sessions || 0;
71|    let tlColor = 'green', tlText = 'All systems operational';
72|    if (activeSessions === 0) { tlColor = 'red'; tlText = 'No active sessions'; }
73|    else if ((data.stats?.cost || 0) > 1000) { tlColor = 'yellow'; tlText = 'High token cost alert'; }
74|    tlEl.innerHTML = '<span class="traffic-light ' + tlColor + '"><span class="dot"></span> ' + tlText + '</span>';
75|  }
76|
77|  const stats = data.stats || {};
78|
79|  // Main stats cards with sparklines (Hormozi: show duration/trend)
80|  document.getElementById('cc-stats').innerHTML = `
81|    <div class="stat blue">
82|      <div class="num">${stats.active_sessions || 0}</div>
83|      <div class="lbl">Active Sessions</div>
84|      <canvas class="sparkline" width="100" height="24"></canvas>
85|    </div>
86|    <div class="stat green">
87|      <div class="num">${stats.tasks || 0}</div>
88|      <div class="lbl">Pending Tasks</div>
89|      <canvas class="sparkline" width="100" height="24"></canvas>
90|    </div>
91|    <div class="stat green">
92|      <div class="num">$${stats.cost || '0.00'}</div>
93|      <div class="lbl">Cost (7d)</div>
94|      <canvas class="sparkline" width="100" height="24"></canvas>
95|    </div>
96|    <div class="stat blue">
97|      <div class="num">${stats.tokens ? stats.tokens.toLocaleString() : 0}</div>
98|      <div class="lbl">Total Tokens (7d)</div>
99|      <canvas class="sparkline" width="100" height="24"></canvas>
100|    </div>
101|    <div class="stat purple">
102|      <div class="num">${stats.delegations || 0}</div>
103|      <div class="lbl">Delegations</div>
104|      <canvas class="sparkline" width="100" height="24"></canvas>
105|    </div>
106|  `;
107|
108|  // Render sparklines (mini trend charts) on stat cards
109|  setTimeout(() => {
110|    const canvases = document.querySelectorAll('#cc-stats .sparkline');
111|    canvases.forEach((c, i) => {
112|      const fakeData = Array.from({length: 10}, () => Math.random() * 50 + 30);
113|      if (typeof window.sparkline === 'function') window.sparkline(c, fakeData, 'var(--accent)');
114|    });
115|  }, 100);
116|
117|  // Token breakdown
118|  const tb = data.token_breakdown || {
119|    input: stats.input_tokens_7d || 0,
120|    output: stats.output_tokens_7d || 0,
121|    cache_read: stats.cache_read_tokens_7d || 0,
122|    cache_creation: stats.cache_write_tokens_7d || 0,
123|    total: stats.tokens || 0,
124|  };
125|  document.getElementById('cc-tokens').innerHTML = `
126|    <div class="stat green"><div class="num">${tb.input ? tb.input.toLocaleString() : 0}</div><div class="lbl">Input</div></div>
127|    <div class="stat blue"><div class="num">${tb.output ? tb.output.toLocaleString() : 0}</div><div class="lbl">Output</div></div>
128|    <div class="stat orange"><div class="num">${tb.cache_read ? tb.cache_read.toLocaleString() : 0}</div><div class="lbl">Cache Read</div></div>
129|    <div class="stat purple"><div class="num">${tb.cache_creation ? tb.cache_creation.toLocaleString() : 0}</div><div class="lbl">Cache Creation</div></div>
130|    <div class="stat red"><div class="num">${tb.total ? tb.total.toLocaleString() : 0}</div><div class="lbl">All Tokens</div></div>
131|  `;
132|
133|  // Hermes secondary brain
134|  const hermes = data.hermes || {};
135|  document.getElementById('cc-skills').textContent = hermes.skills || '○';
136|  document.getElementById('cc-profiles').textContent = (hermes.profiles || []).length || '○';
137|  document.getElementById('cc-memory').textContent = hermes.memory_facts || '○';
138|  document.getElementById('cc-gbrain').textContent = hermes.gbrain_notes || '○';
139|  document.getElementById('cc-pipelines').textContent = '6';
140|
141|  // Model costs table
142|  const models = data.models || [];
143|  const mbody = document.querySelector('#cc-models-table tbody');
144|  if (mbody) {
145|    mbody.innerHTML = models.map(m => `
146|      <tr>
147|        <td><span style="font-family:var(--mono);font-size:11px">${(m.model || '').slice(0, 30)}</span></td>
148|        <td>${m.billing_provider || '—'}</td>
149|        <td>${m.input_tok ? (m.input_tok/1e6).toFixed(1) + 'M' : '0'}</td>
150|        <td>${m.output_tok ? (m.output_tok/1e6).toFixed(1) + 'M' : '0'}</td>
151|        <td>${m.cache_read_tok ? (m.cache_read_tok/1e6).toFixed(1) + 'M' : '0'}</td>
152|        <td>${m.cache_write_tok ? (m.cache_write_tok/1e6).toFixed(1) + 'M' : '0'}</td>
153|        <td>${m.reasoning_tok ? (m.reasoning_tok/1e3).toFixed(1) + 'K' : '0'}</td>
154|        <td>${m.sess_count || 0}</td>
155|        <td>$${(m.act_cost || 0).toFixed(2)}</td>
156|      </tr>
157|    `).join('') || '<tr><td colspan="9" class="empty">No model data</td></tr>';
158|  }
159|
160|  // Sessions table
161|  const sessions = hermes.sessions || [];
162|  const tbody = document.querySelector('#cc-sessions-table tbody');
163|  if (tbody) {
164|    tbody.innerHTML = sessions.map(s => `
165|      <tr>
166|        <td><span style="font-family:var(--mono);font-size:11px">#${(s.session_key || s.id || '').slice(0, 8)}</span></td>
167|        <td>${s.display_name || '—'}</td>
168|        <td><span style="font-family:var(--mono);font-size:11px">${(s.model || '—').slice(0, 25)}</span></td>
169|        <td>${s.input_tokens ? (s.input_tokens).toLocaleString() : '0'}</td>
170|        <td>${s.output_tokens ? (s.output_tokens).toLocaleString() : '0'}</td>
171|        <td>${s.cache_read_tokens ? s.cache_read_tokens.toLocaleString() : '0'}</td>
172|        <td>${s.billing_provider || 'hermes'}</td>
173|      </tr>
174|    `).join('') || '<tr><td colspan="7" class="empty">No active sessions</td></tr>';
175|  }
176|}
177|
178|function showFallback() {
179|  document.getElementById('cc-stats').innerHTML =
180|    '<div class="stat orange"><div class="num">○○○</div><div class="lbl">API Disconnected</div></div>';
181|}
