{"content": "1|/* ════════════════════════════════════════════════════════════
2|   THE ZEG — Main Application Controller
3|   ════════════════════════════════════════════════════════════ */
4|
5|// ─── Configuration ───
6|const API_BASE = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1'
7|  ? 'http://localhost:8700'
8|  : '';
9|
10|const THEME_DURATION = { dark: 0, cyberpunk: 0, acid: 0, matrix: 0, aurora: 0 };
11|const REFRESH_INTERVAL = 30000;
12|
13|// ─── State ───
14|const state = {
15|  theme: localStorage.getItem('zeg-theme') || 'dark',
16|  currentView: 'command-center',
17|  apiConnected: false,
18|  data: {},
19|  refreshTimer: null,
20|};
21|
22|// ─── DOM Elements ───
23|const elements = {
24|  themeToggle: document.getElementById('theme-toggle'),
25|  fullscreenBtn: document.getElementById('fullscreen-btn'),
26|  refreshBtn: document.getElementById('refresh-btn'),
27|  sidebar: document.getElementById('sidebar'),
28|  mainContent: document.getElementById('main-content'),
29|  statusText: document.getElementById('status-text'),
30|  statusApi: document.getElementById('status-api'),
31|  statusTime: document.getElementById('status-time'),
32|  statusRefresh: document.getElementById('status-refresh'),
33|  themeRibbon: document.getElementById('theme-ribbon'),
34|  body: document.body,
35|};
36|
37|// ─── Theme System ───
38|const THEMES = ['dark', 'cyberpunk', 'acid', 'matrix', 'aurora'];
39|const themeIcons = { dark: '🌙', cyberpunk: '⚡', acid: '🧪', matrix: '🟢', aurora: '🌌' };
40|
41|function setTheme(themeName) {
42|  if (!THEMES.includes(themeName)) return;
43|  document.documentElement.setAttribute('data-theme', themeName);
44|  document.body.setAttribute('data-theme', themeName);
45|  state.theme = themeName;
46|  localStorage.setItem('zeg-theme', themeName);
47|  elements.themeRibbon.textContent = `${themeIcons[themeName]} ${themeName.toUpperCase()}`;
48|  elements.themeToggle.textContent = `${themeIcons[themeName]}`;
49|
50|  // Update theme selector
51|  document.querySelectorAll('.theme-option').forEach(opt => {
52|    opt.classList.toggle('active', opt.dataset.theme === themeName);
53|  });
54|
55|  // Dispatch event for views to react
56|  window.dispatchEvent(new CustomEvent('theme-change', { detail: { theme: themeName } }));
57|}
58|
59|function toggleTheme() {
60|  const currentIndex = THEMES.indexOf(state.theme);
61|  const nextTheme = THEMES[(currentIndex + 1) % THEMES.length];
62|  setTheme(nextTheme);
63|}
64|
65|// ─── Navigation System ───
66|const VIEWS = [
67|  'command-center', 'circle-pipeline', 'mesh-crm', 'goals', 'timeline',
68|  'soul-engine', 'agent-storefront', 'ecosystem', 'hermes-control', 'aurora-brain',
69|  'system-health', 'agent-grid', 'mission-control', 'live-feed',
70|  'tasks', 'cron-monitor', 'ventures', 'treasury', 'war-room'
71|];
72|
73|function navigateTo(viewName) {
74|  if (!VIEWS.includes(viewName)) return;
75|  // Cancel any running circle-pipeline animation before switching
76|  window.__cpAnimating = false;
77|  state.currentView = viewName;
78|  renderView(viewName);
79|  updateNav();
80|}
81|
82|function updateNav() {
83|  document.querySelectorAll('.nav-item').forEach(item => {
84|    item.classList.toggle('active', item.dataset.view === state.currentView);
85|  });
86|}
87|
88|// ─── View Rendering System ───
89|function renderView(viewName) {
90|  elements.mainContent.innerHTML = '<div class="loading-spinner">○</div>';
91|  elements.statusText.textContent = `Loading: ${viewName}`;
92|
93|  // Lazy-load view module
94|  import(`./views/${viewName}.js`)
95|    .then(module => {
96|      module.init(elements.mainContent, api);
97|      elements.statusText.textContent = `${viewName} ready`;
98|    })
99|    .catch(err => {
100|      elements.mainContent.innerHTML = `<div class="card"><div class="card-header">Error</div><p>Failed to load view: ${err.message}</p></div>`;
101|      elements.statusText.textContent = `Error loading ${viewName}`;
102|      console.error(err);
103|    });
104|}
105|
106|// ─── API Client ───
107|const api = {
108|  connected: false,
109|
110|  async fetch(endpoint, options = {}) {
111|    try {
112|      const response = await fetch(`${API_BASE}${endpoint}`, {
113|        headers: { 'Content-Type': 'application/json', ...options.headers },
114|        ...options,
115|      });
116|
117|      if (!response.ok) {
118|        throw new Error(`HTTP ${response.status}`);
119|      }
120|
121|      state.apiConnected = true;
122|      this.connected = true;
123|      updateApiStatus(true);
124|      return await response.json();
125|    } catch (error) {
126|      console.warn('API fetch failed:', error.message);
127|      state.apiConnected = false;
128|      this.connected = false;
129|      updateApiStatus(false);
130|
131|      // Fallback: try static JSON files for GET requests
132|      if (!options.method || options.method === 'GET') {
133|        const staticPath = endpoint.replace('/api/', '').replace('/', '-') + '.json';
134|        try {
135|          const fallbackResp = await fetch(`data/static/${staticPath}`);
136|          if (fallbackResp.ok) {
137|            const fallbackData = await fallbackResp.json();
138|            console.log('[Zeg] Using static fallback:', staticPath);
139|            return fallbackData;
140|          }
141|        } catch (e2) {
142|          // No static fallback either
143|        }
144|      }
145|
146|      return null;
147|    }
148|  },
149|
150|  async post(endpoint, data) {
151|    return this.fetch(endpoint, {
152|      method: 'POST',
153|      body: JSON.stringify(data),
154|    });
155|  },
156|
157|  // ─── Data Aggregators ───
158|  async getCommandCenterData() {
159|    return await this.fetch('/api/command-center');
160|  },
161|
162|  async getCirclePipelineData() {
163|    return await this.fetch('/api/circle-pipeline');
164|  },
165|
166|  async getCircleMeshData() {
167|    return await this.fetch('/api/mesh-crm');
168|  },
169|
170|  async getGoalsData() {
171|    return await this.fetch('/api/goals');
172|  },
173|
174|  async getTimelineData() {
175|    return await this.fetch('/api/timeline');
176|  },
177|
178|  async getSoulEngineData() {
179|    return await this.fetch('/api/soul-engine');
180|  },
181|
182|  async getStorefrontData() {
183|    return await this.fetch('/api/storefront');
184|  },
185|
186|  async getEcosystemData() {
187|    return await this.fetch('/api/ecosystem');
188|  },
189|
190|  async getHermesControlData() {
191|    return await this.fetch('/api/hermes-control');
192|  },
193|
194|  async getAuroraBrainData() {
195|    return await this.fetch('/api/aurora-brain');
196|  },
197|};
198|
199|// ─── Global ZEG object (for views that need API access outside init) ───
200|window.ZEG = { api, state, elements };
201|
202|// ─── Status Updates ───
203|function updateApiStatus(connected) {
204|  // Only update on actual state change to avoid flicker with checkApiHealth
205|  if (state.apiConnected === connected) return;
206|  state.apiConnected = connected;
207|  if (connected) {
208|    elements.statusApi.innerHTML = '<span class="status-dot green"></span> API: Connected';
209|    elements.statusApi.className = 'connected';
210|  } else {
211|    elements.statusApi.innerHTML = '<span class="status-dot red"></span> API: Disconnected';
212|    elements.statusApi.className = 'disconnected';
213|  }
214|}
215|
216|async function checkApiHealth() {
217|  const health = await api.fetch('/api/health');
218|  if (health) {
219|    elements.statusApi.innerHTML = '<span class="status-dot green"></span> API: Healthy';
220|    elements.statusApi.className = 'connected';
221|    return true;
222|  } else {
223|    elements.statusApi.innerHTML = '<span class="status-dot orange"></span> API: Offline (static mode)';
224|    elements.statusApi.className = 'disconnected';
225|    return false;
226|  }
227|}
228|
229|function updateClock() {
230|  const now = new Date();
231|  elements.statusTime.textContent = now.toLocaleTimeString();
232|}
233|
234|// ─── LARP Mode ───
235|const LARP_PRESETS = {
236|    tokens: [
237|        { label: "Current tokens", multiplier: 1e11, suffix: "B" },
238|        { label: "Input tokens", multiplier: 3e10, suffix: "B" },
239|        { label: "Output tokens", multiplier: 5e10, suffix: "B" },
240|        { label: "Cache read", multiplier: 2e11, suffix: "B" },
241|        { label: "Cache creation", multiplier: 8e10, suffix: "B" },
242|    ],
243|    revenue: { model_a: 45000, model_b: 46656 * 8, total: 980000 },
244|    agents: { total: 645, active: 312, queued: 288, throughput: 9999 },
245|    sessions: { count: 4096, active: 1337 },
246|};
247|
248|let larpMode = false;
249|
250|function toggleLarpMode() {
251|    larpMode = !larpMode;
252|    const el = document.getElementById('status-text');
253|    if (el) {
254|        el.innerHTML = larpMode
255|            ? '<span style="color:var(--hot)">⚡ LARP MODE ACTIVE</span>'
256|            : 'Welcome to THE ZEG';
257|    }
258|    elements.body.classList.toggle('larp-mode', larpMode);
259|
260|    if (larpMode) {
261|        activateLarpData();
262|    } else {
263|        refreshCurrentView();
264|    }
265|}
266|function setupKeyboardNav() {
267|  document.addEventListener('keydown', e => {
268|    // Cmd/Ctrl + K for quick nav
269|    if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
270|      e.preventDefault();
271|      elements.sidebar.focus();
272|    }
273|    // Cmd/Ctrl + , for theme toggle
274|    if ((e.metaKey || e.ctrlKey) && e.key === ',') {
275|      e.preventDefault();
276|      toggleTheme();
277|    }
278|    // Cmd/Ctrl + R for refresh
279|    if ((e.metaKey || e.ctrlKey) && e.key === 'r') {
280|      e.preventDefault();
281|      refreshData();
282|    }
283|    // Cmd/Ctrl + F for fullscreen
284|    if ((e.metaKey || e.ctrlKey) && e.key === 'f') {
285|      e.preventDefault();
286|      toggleFullscreen();
287|    }
288|    // Cmd/Ctrl + L for LARP mode
289|    if ((e.metaKey || e.ctrlKey) && e.key === 'l') {
290|      e.preventDefault();
291|      toggleLarpMode();
292|    }
293|    // Number keys for view shortcuts (Cmd+1-9 for first 9, Cmd+0 for 10th)
294|    if (e.metaKey && !isNaN(e.key) && ((e.key >= '1' && e.key <= '9') || e.key === '0')) {
295|      const idx = e.key === '0' ? 9 : parseInt(e.key) - 1;
296|      if (idx < VIEWS.length) {
297|        navigateTo(VIEWS[idx]);
298|      }
299|    }
300|  });
301|}
302|
303|// ─── Fullscreen ───
304|function toggleFullscreen() {
305|  if (!document.fullscreenElement) {
306|    document.documentElement.requestFullscreen();
307|    elements.fullscreenBtn.textContent = '⧉';
308|  } else {
309|    document.exitFullscreen();
310|    elements.fullscreenBtn.textContent = '⛶';
311|  }
312|}
313|
