624|// ═══ Sparkline Helper (mini charts for stat cards) ═══
625|window.sparkline = function(canvas, data, color = 'var(--accent)') {
626|  if (!canvas || !data || data.length < 2) return;
627|  const ctx = canvas.getContext('2d');
628|  const w = canvas.width, h = canvas.height;
629|  const min = Math.min(...data), max = Math.max(...data);
630|  const range = max - min || 1;
631|  ctx.clearRect(0, 0, w, h);
632|  ctx.beginPath();
633|  ctx.strokeStyle = color;
634|  ctx.lineWidth = 1.5;
635|  ctx.fillStyle = 'rgba(0, 180, 255, 0.05)';
636|  const pts = [];
637|  for (let i = 0; i < data.length; i++) {
638|    const x = (i / (data.length - 1)) * w;
639|    const y = h - ((data[i] - min) / range) * h;
640|    pts.push([x, y]);
641|    if (i === 0) ctx.moveTo(x, y);
642|    else ctx.lineTo(x, y);
643|  }
644|  ctx.stroke();
645|  // Fill area under line
646|  ctx.lineTo(w, h);
647|  ctx.lineTo(0, h);
648|  ctx.closePath();
649|  ctx.fill();
650|};
